/**
 * DESIGN TOKENS SCHEMA
 *
 * Styrer Tailwind CSS v4 design tokens fra Sanity CMS.
 * Endringer her reflekteres automatisk i applikasjonen.
 */
import { defineType, defineField } from 'sanity'

export const designTokens = defineType({
  name: 'designTokens',
  title: 'Design Tokens',
  type: 'document',
  fields: [
    defineField({
      name: 'title',
      title: 'Token Set Navn',
      type: 'string',
      initialValue: 'Klarpakke Design Tokens',
      readOnly: true,
    }),
    defineField({
      name: 'brandColors',
      title: 'Brand Farger',
      type: 'object',
      fields: [
        { name: 'primary', title: 'Primær', type: 'string', initialValue: '#0052FF' },
        { name: 'primaryHover', title: 'Primær Hover', type: 'string', initialValue: '#0047E0' },
        { name: 'primaryLight', title: 'Primær Lys', type: 'string', initialValue: '#dbeafe' },
      ],
    }),
    defineField({
      name: 'semanticColors',
      title: 'Semantiske Farger',
      type: 'object',
      fields: [
        { name: 'success', title: 'Suksess', type: 'string', initialValue: '#22c55e' },
        { name: 'warning', title: 'Advarsel', type: 'string', initialValue: '#f59e0b' },
        { name: 'error', title: 'Feil', type: 'string', initialValue: '#ef4444' },
        { name: 'info', title: 'Info', type: 'string', initialValue: '#3b82f6' },
      ],
    }),
    defineField({
      name: 'darkMode',
      title: 'Dark Mode',
      type: 'object',
      fields: [
        { name: 'bgPrimary', title: 'Bakgrunn Primær', type: 'string', initialValue: '#0a0b0d' },
        { name: 'bgSecondary', title: 'Bakgrunn Sekundær', type: 'string', initialValue: '#161719' },
        { name: 'bgElevated', title: 'Bakgrunn Hevet', type: 'string', initialValue: '#1a1c24' },
        { name: 'textPrimary', title: 'Tekst Primær', type: 'string', initialValue: '#f1f5f9' },
        { name: 'textSecondary', title: 'Tekst Sekundær', type: 'string', initialValue: '#94a3b8' },
        { name: 'border', title: 'Kantlinje', type: 'string', initialValue: 'rgba(255,255,255,0.08)' },
      ],
    }),
    defineField({
      name: 'typography',
      title: 'Typografi',
      type: 'object',
      fields: [
        {
          name: 'fontFamily',
          title: 'Font Familie',
          type: 'string',
          initialValue: 'Inter',
          options: {
            list: [
              { title: 'Inter', value: 'Inter' },
              { title: 'System UI', value: 'system-ui' },
            ],
          },
        },
        { name: 'baseFontSize', title: 'Base Font Størrelse (px)', type: 'number', initialValue: 16 },
      ],
    }),
    defineField({
      name: 'spacing',
      title: 'Spacing',
      type: 'object',
      fields: [
        { name: 'unit', title: 'Base Unit (px)', type: 'number', initialValue: 4 },
        { name: 'scale', title: 'Multiplikator', type: 'number', initialValue: 1 },
      ],
    }),
    defineField({
      name: 'borderRadius',
      title: 'Avrunding',
      type: 'object',
      fields: [
        { name: 'button', title: 'Knapp (px)', type: 'number', initialValue: 12 },
        { name: 'card', title: 'Kort (px)', type: 'number', initialValue: 16 },
        { name: 'input', title: 'Input (px)', type: 'number', initialValue: 10 },
      ],
    }),
    defineField({
      name: 'shadows',
      title: 'Skyggar',
      type: 'object',
      fields: [
        { name: 'card', title: 'Kort Skygge', type: 'string', initialValue: '0 4px 30px rgba(0, 0, 0, 0.1)' },
        { name: 'elevated', title: 'Hevet Skygge', type: 'string', initialValue: '0 20px 50px rgba(0, 0, 0, 0.3)' },
        { name: 'glow', title: 'Brand Glow', type: 'string', initialValue: '0 0 40px rgba(0, 82, 255, 0.3)' },
      ],
    }),
    defineField({
      name: 'isActive',
      title: 'Aktiv',
      description: 'Sett til false for å bruke fallback verdier fra kode',
      type: 'boolean',
      initialValue: false,
    }),
    defineField({
      name: 'lastUpdated',
      title: 'Sist Oppdatert',
      type: 'datetime',
      readOnly: true,
      initialValue: () => new Date().toISOString(),
    }),
  ],
  preview: {
    select: {
      title: 'title',
      active: 'isActive',
      updated: 'lastUpdated',
    },
    prepare({ title, active, updated }: { title?: string; active?: boolean; updated?: string }) {
      return {
        title: title ?? 'Design Tokens',
        subtitle: `${active ? '✅ Aktiv' : '⏸️ Inaktiv'} - ${updated ? new Date(updated).toLocaleDateString('no') : 'Aldri'}`,
      }
    },
  },
})
